//! `median_blur` against reference vectors generated by `cv2.medianBlur`
//! itself (see `tests/data/opencv_median/generate.py`; generated with
//! OpenCV 5.0.0, and byte-identical with OpenCV 4.14.0): `u8`, `u16` and
//! `f32`, 1 and 3 channels, ksize 3 and 5. The median is an exact order
//! statistic, so every case must match bit for bit.

use kornia_image::{Image, ImageSize};
use kornia_imgproc::filter::{median_blur, MedianBlur};

fn data_dir() -> std::path::PathBuf {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/opencv_median")
}

/// Fixture name: `<dtype>_c<channels>_<H>x<W>`.
fn parse_key(key: &str) -> (String, usize, ImageSize) {
    let parts: Vec<&str> = key.split('_').collect();
    assert_eq!(parts.len(), 3, "unexpected fixture name: {key}");
    let channels = parts[1].strip_prefix('c').unwrap().parse().unwrap();
    let (h, w) = parts[2].split_once('x').expect("HxW");
    let size = ImageSize {
        width: w.parse().unwrap(),
        height: h.parse().unwrap(),
    };
    (parts[0].to_string(), channels, size)
}

fn read<T: Copy, const N: usize>(path: &std::path::Path, from: fn([u8; N]) -> T) -> Vec<T> {
    std::fs::read(path)
        .unwrap()
        .chunks_exact(N)
        .map(|c| from(c.try_into().unwrap()))
        .collect()
}

fn run<T: MedianBlur + Default + std::fmt::Debug, const C: usize, const N: usize>(
    key: &str,
    size: ImageSize,
    from: fn([u8; N]) -> T,
    bits: fn(T) -> u32,
) {
    let dir = data_dir();
    let src = Image::<T, C>::new(size, read(&dir.join(format!("{key}.src")), from)).unwrap();
    for ksize in [3usize, 5] {
        let want = read(&dir.join(format!("{key}.k{ksize}")), from);
        let mut dst = Image::<T, C>::from_size_val(size, T::default()).unwrap();
        median_blur(&src, &mut dst, ksize).unwrap();
        for (i, (&got, &want)) in dst.as_slice().iter().zip(&want).enumerate() {
            assert_eq!(
                bits(got),
                bits(want),
                "{key} k={ksize} element {i}: got {got:?}, cv2 {want:?}"
            );
        }
    }
}

fn run_case<const C: usize>(key: &str, dtype: &str, size: ImageSize) {
    match dtype {
        "u8" => run::<u8, C, 1>(key, size, |b| b[0], u32::from),
        "u16" => run::<u16, C, 2>(key, size, u16::from_le_bytes, u32::from),
        "f32" => run::<f32, C, 4>(key, size, f32::from_le_bytes, f32::to_bits),
        other => panic!("unknown dtype {other}"),
    }
}

#[test]
fn median_blur_matches_cv2_reference_vectors() {
    let mut keys: Vec<String> = std::fs::read_dir(data_dir())
        .unwrap()
        .filter_map(|e| {
            let name = e.unwrap().file_name().into_string().unwrap();
            name.strip_suffix(".src").map(str::to_string)
        })
        .collect();
    keys.sort();
    // 3 dtypes x 2 channel counts x 5 shapes.
    assert_eq!(keys.len(), 30, "missing cv2 fixtures");
    for key in &keys {
        let (dtype, channels, size) = parse_key(key);
        match channels {
            1 => run_case::<1>(key, &dtype, size),
            3 => run_case::<3>(key, &dtype, size),
            n => panic!("unexpected channel count {n}"),
        }
    }
    println!("validated {} cv2-generated fixtures x 2 ksizes", keys.len());
}
